import{_ as l,a0 as p,w as r,s as o,I as i,x as a,a1 as e,A as t,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"在 Linux 上安装 MariaDB 或 MySQL | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安装 MariaDB 或 MySQL | LCTT (202010) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安装 MariaDB 或 MySQL | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安装 MariaDB 或 MySQL | LCTT (202010) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20201013 Install MariaDB or MySQL on Linux","title":"在 Linux 上安装 MariaDB 或 MySQL","tag":"202010","desc":""},"relativePath":"202010/20201013 Install MariaDB or MySQL on Linux.md","filePath":"[post].md"}'),u={name:"202010/20201013 Install MariaDB or MySQL on Linux.md"};function h(g,s,m,b,k,y){const n=p("Link");return r(),o("div",null,[s[21]||(s[21]=i("h1",{id:"在-linux-上安装-mariadb-或-mysql",tabindex:"-1"},[a("在 Linux 上安装 MariaDB 或 MySQL "),i("a",{class:"header-anchor",href:"#在-linux-上安装-mariadb-或-mysql","aria-label":"Permalink to “在 Linux 上安装 MariaDB 或 MySQL”"},"​")],-1)),s[22]||(s[22]=i("blockquote",null,[i("p",null,"开始在 Linux 系统上使用开源的 SQL 数据库吧。")],-1)),s[23]||(s[23]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202010/22/144122hkkqrs2dhi9c7kif.jpg",alt:""})],-1)),i("p",null,[e(n,{href:"https://mariadb.org/"},{default:t(()=>[...s[0]||(s[0]=[a("MariaDB",-1)])]),_:1}),s[2]||(s[2]=a(" 和 ",-1)),e(n,{href:"https://www.mysql.com/"},{default:t(()=>[...s[1]||(s[1]=[a("MySQL",-1)])]),_:1}),s[3]||(s[3]=a(" 都是使用 SQL 的开源数据库，并且共享相同的初始代码库。MariaDB 是 MySQL 的替代品，你可以使用相同的命令（",-1)),s[4]||(s[4]=i("code",null,"mysql",-1)),s[5]||(s[5]=a("）与 MySQL 和 MariaDB 数据库进行交互。因此，本文同时适用于 MariaDB 和 MySQL。",-1))]),s[24]||(s[24]=d(`<h3 id="安装-mariadb" tabindex="-1">安装 MariaDB <a class="header-anchor" href="#安装-mariadb" aria-label="Permalink to “安装 MariaDB”">​</a></h3><p>你可以使用你的 Linux 发行版的包管理器安装 MariaDB。在大多数发行版上，MariaDB 分为服务器包和客户端包。服务器包提供了数据库“引擎”，即 MariaDB 在后台运行（通常在物理服务器上）的部分，它监听数据输入或数据输出请求。客户端包提供了 <code>mysql</code> 命令，你可以用它来与服务器通信。</p><p>在 RHEL、Fedora、CentOS 或类似的发行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install mariadb mariadb-server</span></span></code></pre></div><p>在 Debian、Ubuntu、Elementary 或类似的发行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install mariadb-client mariadb-server</span></span></code></pre></div><p>其他操作系统可能会以不同的打包系统封装 MariaDB，所以你可能需要搜索你的软件仓库来了解你的发行版的维护者是如何提供它的。</p><h3 id="启动-mariadb" tabindex="-1">启动 MariaDB <a class="header-anchor" href="#启动-mariadb" aria-label="Permalink to “启动 MariaDB”">​</a></h3><p>因为 MariaDB 被设计为部分作为数据库服务器，它可以在一台计算机上运行，并从另一台计算机上进行管理。只要你能访问运行它的计算机，你就可以使用 <code>mysql</code> 命令来管理数据库。在写这篇文章时，我在本地计算机上运行了 MariaDB，但你同样可与远程系统上托管的 MariaDB 数据库进行交互。</p><p>在启动 MariaDB 之前，你必须创建一个初始数据库。在初始化其文件结构时，你应该定义你希望 MariaDB 使用的用户。默认情况下，MariaDB 使用当前用户，但你可能希望它使用一个专用的用户帐户。你的包管理器可能为你配置了一个系统用户和组。使用 <code>grep</code> 查找是否有一个 <code>mysql</code> 组：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep mysql /etc/group</span></span>
<span class="line"><span>mysql:x:27:</span></span></code></pre></div><p>你也可以在 <code>/etc/passwd</code> 中寻找这个专门的用户，但通常情况下，有组就会有用户。如果没有专门的 <code>mysql</code> 用户和组，可以在 <code>/etc/group</code> 中寻找一个明显的替代品（比如 <code>mariadb</code>）。如果没有，请阅读你的发行版文档来了解 MariaDB 是如何运行的。</p><p>假设你的安装使用 <code>mysql</code>，初始化数据库环境：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mysql_install_db --user=mysql</span></span>
<span class="line"><span>Installing MariaDB/MySQL system tables in &#39;/var/lib/mysql&#39;...</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>这一步的结果显示了接下来你必须执行的配置 MariaDB 的任务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PLEASE REMEMBER TO SET A PASSWORD FOR THE MariaDB root USER !</span></span>
<span class="line"><span>To do so, start the server, then issue the following commands:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&#39;/usr/bin/mysqladmin&#39; -u root password &#39;new-password&#39;</span></span>
<span class="line"><span>&#39;/usr/bin/mysqladmin&#39; -u root -h $(hostname) password &#39;new-password&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Alternatively you can run:</span></span>
<span class="line"><span>&#39;/usr/bin/mysql_secure_installation&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>which will also give you the option of removing the test</span></span>
<span class="line"><span>databases and anonymous user created by default.  This is</span></span>
<span class="line"><span>strongly recommended for production servers.</span></span></code></pre></div><p>使用你的发行版的初始化系统启动 MariaDB：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start mariadb</span></span></code></pre></div><p>在启动时启用 MariaDB 服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now mariadb</span></span></code></pre></div><p>现在你已经有了一个 MariaDB 服务器，为它设置一个密码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysqladmin -u root password &#39;myreallysecurepassphrase&#39;</span></span>
<span class="line"><span>mysqladmin -u root -h $(hostname) password &#39;myreallysecurepassphrase&#39;</span></span></code></pre></div><p>最后，如果你打算在生产服务器上使用它，请在上线前运行 <code>mysql_secure_installation</code> 命令。</p><hr>`,24)),i("p",null,[s[7]||(s[7]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/20/10/mariadb-mysql-linux"},{default:t(()=>[...s[6]||(s[6]=[a("https://opensource.com/article/20/10/mariadb-mysql-linux",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[8]||(s[8]=[a("Seth Kenlon",-1)])]),_:1}),s[13]||(s[13]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[9]||(s[9]=[a("lujun9972",-1)])]),_:1}),s[14]||(s[14]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[10]||(s[10]=[a("geekpi",-1)])]),_:1}),s[15]||(s[15]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[16]||(s[16]=[a("LCTT",-1)])]),_:1}),s[19]||(s[19]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[17]||(s[17]=[a("Linux中国",-1)])]),_:1}),s[20]||(s[20]=a(" 荣誉推出",-1))])])}const D=l(u,[["render",h]]);export{M as __pageData,D as default};
